// Konversi array jadi map untuk lookup O(1)
function indexByKey<T extends Record<string, unknown>>(
  arr: T[],
  key: keyof T
): Record<string, T> {
  return arr.reduce((map, item) => {
    map[String(item[key])] = item;
    return map;
  }, {} as Record<string, T>);
}

const produkList: Produk[] = [
  { id: 1, nama: 'Kaos', harga: 75000 },
  { id: 2, nama: 'Celana', harga: 150000 },
];

