type MungkinNull = string | null | undefined;

type PastiAda = NonNullable<MungkinNull>;
// PastiAda = string

// Berguna setelah validasi
function prosesData(input: string | null | undefined) {
  if (!input) {
    throw new Error('Input tidak boleh kosong');
  }
  // Setelah validasi, kita tahu input pasti string
  // Tapi TS masih anggap string | null | undefined
  // Kita bisa cast:
  const data: NonNullable<typeof input> = input;
  return data.toUpperCase(); // ✅
}

// Atau lebih simpel, gunakan narrowing:
function prosesData2(input: string | null | undefined): string {
  if (input == null) throw new Error('Input kosong');
  return input.toUpperCase(); // TS narrow otomatis ke string
}
